`,d.jsx(o.p,{children:"I've come a long way exploring the many different branches of Computer Science during my time at Full Sail. After a lot of soul searching, I found myself really enjoying web development, especially the frontend aspect of it."}),`
`,d.jsxs(o.p,{children:["My main goal for this capstone project is to keep exploring and improving in this craft. And it all begins with this blog, fully created by yours truly, simply using React and ",d.jsx(o.a,{href:"https://mdxjs.com",children:"MDX"}),"."]}),`
`,d.jsx(o.p,{children:"I've already built a few sites with React, and I hope to make this site my portfolio in the future. But for now, it serves as my personal blog."}),`
`,d.jsx(o.p,{children:"MDX is a new technology for me, but in short, it allows the use of JSX components inside Markdown files, adding an extra layer of interactivity to my blog posts. For this initial post, I don’t really need it, but I included it to make this site a little more interesting and to save myself a future headache if I want to add React components later."}),`
`,d.jsx(o.p,{children:"Looking ahead, in the coming months, I hope to collaborate with Echelon and work with their app development team to create better UI for their smart mirror. If that doesn’t work out, I’m also excited to team up with my classmates to build one of our pitched projects."}),`
`,d.jsx(o.p,{children:"Whatever happens, I’m satisfied with my journey so far and optimistic about what’s ahead :)"})]})}function ig(u={}){const{wrapper:o}=u.components||{};return o?d.jsx(o,{...u,children:d.jsx(bh,{...u})}):bh(u)}const Wh=Object.freeze(Object.defineProperty({__proto__:null,default:ig,frontmatter:ng},Symbol.toStringTag,{value:"Module"})),ug={title:"Starting with Echelon!",date:"8/17/2025",wordCount:329};function _h(u){const o={a:"a",li:"li",p:"p",ul:"ul",...u.components};return d.jsxs(d.Fragment,{children:[d.jsxs(o.p,{children:["I just wrapped up the second week of my capstone project at Full Sail University, and I’m excited to share that I’ll be working with Echelon alongside my classmates! This means, we’ll be helping develop features for their ",d.jsx(o.a,{href:"https://echelonfit.com/products/echelon-reflect-touch-50-fitness-mirror-for-bundles",children:"Reflect smart mirror"})," UI."]}),`
`,d.jsx(o.p,{children:"My background is mostly in web development, so I’m excited to see what comes from developing apps instead. Since we’re dealing with Android development, we’ll be using Kotlin and Jetpack Compose (two technologies I’ve never explored before)."}),`
`,d.jsx(o.p,{children:"In my research, I noticed these two share a lot of similarities with JavaScript and React, and the more I compared them, the more it started to make sense. Kotlin closely resembles TypeScript in that it has strong explicit types, null safety, and modern syntax while still being compatible with older code. So, Kotlin can be thought of as a stricter, Android-focused version of TypeScript, providing the core functionality for the app."}),`
`,d.jsx(o.p,{children:"On the UI side, we’ll be using Jetpack Compose, which is a declarative UI framework similar to React. Both frameworks use functions to build the UI: React has components, while Compose has composables. They also both use state to track changes in the UI and re-render specific elements when needed. Instead of returning HTML tags like in React, Compose uses functions for everything; even elements on screen like buttons and text are functions. Another key difference is styling: React uses CSS, while Compose uses modifiers to handle layout and styles."}),`
`,d.jsx(o.p,{children:"There’s still a long way to go, but I’m excited to learn Android development and eventually build multiplatform apps in the future!"}),`
`,d.jsx(o.p,{children:"I have found these similarities through resources like:"}),`
`,d.jsxs(o.ul,{children:[`
